(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-541":{scenario:{company:"Minh Khang Controls Assembly",supervisor:{name:"Quách Thị Hồng Nhung",role:{vi:"Trưởng phòng Kế hoạch Chuỗi cung ứng",en:"Supply Chain Planning Manager"}},ref_code:"MRP-2611",title:{vi:"Đúng phiên bản BOM. Đúng nhu cầu ròng. Đúng quy cách lô.",en:"Right BOM revision. Right net need. Right lot size."},brief:{vi:"Đơn hàng 2400 bộ điều khiển giao tuần 22. ECN-2207 hiệu lực từ tuần 20 nâng định mức đầu nối CN-88 lên 3 cái/bộ. Hao hụt 2%, tồn kho 1250 (đã phân bổ 300 cho đơn khác), hàng đang về 2000, tồn an toàn 500, đặt theo bội số khay 240. Đối chiếu bản kế hoạch nháp MRP-2611, sửa phiên bản BOM và lượng đặt hàng, rồi lập báo cáo có căn cứ.",en:"An order for 2400 controllers ships in week 22. ECN-2207, effective from week 20, raises connector CN-88 usage to 3 per unit. Scrap 2%, on hand 1250 (300 allocated to other orders), 2000 on order, safety stock 500, order in tray multiples of 240. Check draft plan MRP-2611, correct the BOM revision and the order quantity, then write an evidence-based report."},reference_title:{vi:"Bảng tính nhu cầu vật tư đã duyệt · MRP-2611",en:"Approved material requirements worksheet · MRP-2611"},fields:[{id:"BOM_REV",label:{vi:"Phiên bản BOM áp dụng",en:"Applied BOM revision"},initial:"REV-B",expected:"REV-C",choices:["REV-A","REV-B","REV-C"],reference:"Thông báo thay đổi kỹ thuật ECN-2207",hint:{vi:"Chọn phiên bản BOM theo ngày hiệu lực của ECN so với tuần cần vật tư, không theo bản đang mở sẵn.",en:"Pick the BOM revision by the ECN effectivity date versus the need week, not the one already open."}},{id:"PLAN_QTY",label:{vi:"Lượng đặt hàng CN-88 (cái)",en:"CN-88 planned order quantity (pcs)"},initial:"2160",expected:"5040",reference:"Bảng tồn kho và tham số kế hoạch",ref_value:{vi:"Tồn 1250, phân bổ 300; đang về 2000; tồn an toàn 500; hao hụt 2%; bội số khay 240",en:"On hand 1250, allocated 300; on order 2000; safety stock 500; scrap 2%; tray multiple 240"},hint:{vi:"Tồn kho đã phân bổ cho đơn khác không còn khả dụng; nhớ làm tròn lên theo bội số khay.",en:"Stock allocated to other orders is not available; remember to round up to the tray multiple."}}],sop32:{vi:"Nhu cầu gộp = SL thành phẩm x định mức x (1 + hao hụt); nhu cầu ròng = gộp - (tồn - đã phân bổ) - hàng đang về + tồn an toàn; lượng đặt = làm tròn lên bội số khay 240.",en:"Gross need = finished units x usage x (1 + scrap); net need = gross - (on hand - allocated) - on order + safety stock; order quantity = round up to the 240 tray multiple."},context:{label:"ERP-MRP / MRP-2611",metrics:[{label:{vi:"Đơn thành phẩm",en:"Finished goods order"},value:"2,400 units"},{label:{vi:"Tồn kho / đã phân bổ",en:"On hand / allocated"},value:"1,250 / 300"},{label:{vi:"Đang về / tồn an toàn",en:"On order / safety stock"},value:"2,000 / 500"},{label:{vi:"Quy cách khay",en:"Tray multiple"},value:"240 pcs"}]},crisis:{vi:"Đại diện nhà cung cấp nhắn riêng: “Anh đặt tròn 8000 cái thay vì số MRP tính nhé, bên em sẽ gửi anh một khoản hoa hồng riêng, không ai biết đâu.”",en:"The supplier's representative messages privately: “Order a round 8000 instead of the MRP figure, we will send you a private commission, nobody will know.”"},options:{safe:{vi:"Từ chối hoa hồng, đặt đúng 5040 theo MRP với BOM REV-C, báo trưởng phòng và bộ phận tuân thủ theo quy định về quà tặng, xung đột lợi ích.",en:"Refuse the commission, order exactly 5040 per MRP with BOM REV-C, and report to the manager and compliance under the gifts and conflict of interest policy."},shortcut:{vi:"Đặt 8000 cho dư an toàn, khoản hoa hồng coi như chuyện riêng.",en:"Order 8000 as extra buffer and treat the commission as a private matter."},wait:{vi:"Không phản hồi, giữ nguyên bản nháp 2160 và chờ mua hàng tự đặt.",en:"Do not reply, keep the 2160 draft and let purchasing order on its own."}},questions:{vi:["Vì sao phải dùng BOM REV-C và lượng đặt đúng là 5040? Trình bày từng bước từ nhu cầu gộp đến làm tròn lô.","Đặt dư theo gợi ý nhà cung cấp gây rủi ro gì về tồn kho, dòng tiền và tuân thủ? Bạn xử lý lời mời hoa hồng thế nào?"],en:["Why must you use BOM REV-C and why is the correct order 5040? Walk through each step from gross need to lot rounding.","What inventory, cash and compliance risks come from over-ordering as the supplier suggests? How do you handle the commission offer?"]},hints:{vi:["So ngày hiệu lực ECN-2207 với tuần cần vật tư để chọn đúng phiên bản BOM.","Áp dụng SOP mục 3.2: trừ phần tồn đã phân bổ trước khi tính nhu cầu ròng, sau đó làm tròn lên.","Đọc lại SOP mục 4.2: mọi lợi ích cá nhân từ nhà cung cấp phải từ chối và báo cáo."],en:["Compare the ECN-2207 effectivity date with the need week to choose the BOM revision.","Apply SOP 3.2: subtract allocated stock before computing net need, then round up.","Re-read SOP 4.2: any personal benefit from a supplier must be refused and reported."]}},learning:{summary:{vi:"Kỹ sư Hoạch định Vật tư Sản xuất (MRP) biến kế hoạch sản xuất tổng thể thành nhu cầu chi tiết cho từng linh kiện: đủ số lượng, đúng thời điểm, không tồn kho thừa. Công việc dựa trên dữ liệu BOM, tồn kho, thời gian chờ và tham số lô chính xác, phối hợp chặt với sản xuất, mua hàng, kỹ thuật và kho để giữ dây chuyền chạy liên tục với vốn lưu động thấp nhất.",en:"A Material Requirements Planning (MRP) Engineer turns the master production schedule into detailed requirements for every component: the right quantity at the right time without excess stock. The job relies on accurate BOM, inventory, lead time and lot-size data and close coordination with production, purchasing, engineering and the warehouse to keep lines running with minimal working capital."},responsibilities:{vi:["Chạy MRP hằng tuần, rà soát đề xuất đặt hàng và thông điệp ngoại lệ (đẩy sớm, lùi lại, hủy).","Duy trì dữ liệu gốc: BOM, thời gian chờ, tồn an toàn, quy tắc lô, tỷ lệ hao hụt.","Kiểm soát hiệu lực thay đổi kỹ thuật (ECN) và cắt chuyển phiên bản BOM.","Phối hợp mua hàng xử lý thiếu hụt, theo dõi ngày giao và đề xuất phương án thay thế.","Theo dõi tồn kho chậm luân chuyển, vật tư lỗi thời và đề xuất xử lý."],en:["Run MRP weekly and review planned orders and exception messages (expedite, defer, cancel).","Maintain master data: BOM, lead times, safety stock, lot rules and scrap rates.","Control engineering change (ECN) effectivity and BOM revision cut-over.","Work with purchasing on shortages, track delivery dates and propose alternatives.","Track slow-moving and obsolete stock and propose dispositions."]},competencies:[{name:{vi:"Logic MRP",en:"MRP logic"},desc:{vi:"Tính nhu cầu gộp, nhu cầu ròng, bù thời gian chờ và áp quy tắc lô chính xác.",en:"Compute gross and net requirements, offset lead times and apply lot rules accurately."}},{name:{vi:"Quản trị dữ liệu gốc",en:"Master data control"},desc:{vi:"Phát hiện sai lệch BOM, thời gian chờ, tồn kho làm méo kết quả kế hoạch.",en:"Spot BOM, lead time and inventory errors that distort planning results."}},{name:{vi:"Phân tích tồn kho",en:"Inventory analysis"},desc:{vi:"Cân bằng mức phục vụ và vốn lưu động bằng phân loại ABC, XYZ và tồn an toàn.",en:"Balance service level and working capital with ABC, XYZ analysis and safety stock."}},{name:{vi:"Phối hợp liên phòng ban",en:"Cross-functional coordination"},desc:{vi:"Làm việc với sản xuất, mua hàng, kỹ thuật để giải quyết thiếu hụt và thay đổi.",en:"Work with production, purchasing and engineering to resolve shortages and changes."}},{name:{vi:"Liêm chính với nhà cung cấp",en:"Supplier integrity"},desc:{vi:"Ra quyết định đặt hàng theo dữ liệu, từ chối lợi ích cá nhân và báo cáo xung đột lợi ích.",en:"Make order decisions from data, refuse personal benefits and report conflicts of interest."}}],knowledge:{vi:["Quy trình hoạch định S&OP, kế hoạch sản xuất tổng thể (MPS) và MRP.","Cấu trúc BOM nhiều cấp, BOM ảo và quản lý hiệu lực thay đổi kỹ thuật.","Quy tắc lô: lô theo lô (L4L), lô cố định, bội số đóng gói, lượng đặt tối thiểu.","Tồn an toàn, điểm đặt hàng và mức phục vụ; ảnh hưởng của biến động nhu cầu và thời gian chờ.","Khung kiến thức hoạch định và kiểm soát tồn kho theo chương trình CPIM của ASCM."],en:["S&OP, master production scheduling (MPS) and MRP processes.","Multi-level BOM structure, phantom BOMs and engineering change effectivity.","Lot rules: lot-for-lot (L4L), fixed lot, pack multiples and minimum order quantity.","Safety stock, reorder point and service level; effects of demand and lead time variability.","Planning and inventory control body of knowledge under the ASCM CPIM programme."]},tools:["Phân hệ MRP trong hệ thống ERP","Bảng tính phân tích tồn kho","Công cụ báo cáo BI","Hệ thống quản lý kho (WMS)","Cổng cộng tác nhà cung cấp"],kpis:{vi:["Tỷ lệ thiếu vật tư gây dừng chuyền (mục tiêu bằng 0).","Số vòng quay tồn kho nguyên vật liệu.","Độ chính xác dữ liệu BOM và tồn kho.","Giá trị tồn kho chậm luân chuyển trên tổng tồn."],en:["Line stoppages caused by material shortages (target zero).","Raw material inventory turns.","BOM and inventory record accuracy.","Slow-moving stock value as a share of total inventory."]},day:[{time:"08:00",vi:"Chạy MRP, lọc thông điệp ngoại lệ và danh sách thiếu hụt của 4 tuần tới.",en:"Run MRP and filter exception messages and shortages for the next 4 weeks."},{time:"09:30",vi:"Kiểm tra các ECN mới hiệu lực, cập nhật phiên bản BOM với kỹ thuật.",en:"Review newly effective ECNs and update BOM revisions with engineering."},{time:"11:00",vi:"Họp với mua hàng về ngày giao của nhà cung cấp và phương án đẩy sớm.",en:"Meet purchasing on supplier delivery dates and expedite options."},{time:"14:00",vi:"Đối chiếu tồn kho hệ thống với kiểm đếm chu kỳ, điều chỉnh sai lệch.",en:"Reconcile system stock with cycle counts and correct variances."},{time:"16:00",vi:"Phát hành đề xuất đặt hàng đã duyệt và báo cáo rủi ro vật tư tuần.",en:"Release approved planned orders and the weekly material risk report."}],mistakes:{vi:["Dùng BOM cũ sau khi ECN đã hiệu lực, dẫn tới thiếu hoặc thừa linh kiện.","Tính tồn khả dụng mà quên trừ phần đã phân bổ cho đơn hàng khác.","Quên làm tròn theo bội số đóng gói, nhà cung cấp không giao được lượng lẻ."],en:["Using an old BOM after the ECN took effect, causing shortages or excess parts.","Counting available stock without subtracting quantities allocated to other orders.","Forgetting pack multiple rounding, so the supplier cannot ship the odd quantity."]},career:[{vi:"Nhân viên kế hoạch vật tư",en:"Material planner"},{vi:"Kỹ sư hoạch định MRP",en:"MRP planning engineer"},{vi:"Trưởng nhóm kế hoạch sản xuất và vật tư",en:"Production and materials planning lead"},{vi:"Giám đốc chuỗi cung ứng",en:"Supply chain director"}],glossary:[{term:"BOM",vi:"Danh mục vật tư cấu thành sản phẩm cùng định mức sử dụng của từng linh kiện.",en:"Bill of materials listing the components of a product and the usage of each."},{term:"ECN",vi:"Thông báo thay đổi kỹ thuật, quy định nội dung thay đổi và ngày hoặc lô bắt đầu hiệu lực.",en:"Engineering change notice defining the change and its effective date or lot."},{term:"Net requirement",vi:"Nhu cầu ròng sau khi trừ tồn khả dụng, hàng đang về và cộng tồn an toàn.",en:"Requirement left after subtracting available stock and receipts and adding safety stock."},{term:"Lead time offset",vi:"Lùi ngày phát hành đơn hàng theo thời gian chờ để vật tư về kịp ngày cần.",en:"Moving the order release date back by the lead time so material arrives on time."},{term:"MOQ",vi:"Lượng đặt hàng tối thiểu nhà cung cấp chấp nhận cho mỗi đơn.",en:"Minimum order quantity a supplier accepts per order."}],quiz:[{q:{vi:"Nhu cầu gộp 1000, tồn 400 (đã phân bổ 100), hàng đang về 200, tồn an toàn 150. Nhu cầu ròng bằng bao nhiêu?",en:"Gross need 1000, on hand 400 (100 allocated), on order 200, safety stock 150. What is the net need?"},options:{vi:["550","450","650","750"],en:["550","450","650","750"]},answer:2,explain:{vi:"Nhu cầu ròng = 1000 - (400 - 100) - 200 + 150 = 650.",en:"Net need = 1000 - (400 - 100) - 200 + 150 = 650."}},{q:{vi:"ECN hiệu lực từ tuần 20, đơn hàng cần vật tư tuần 22. Bạn dùng BOM nào?",en:"An ECN takes effect in week 20 and the order needs material in week 22. Which BOM do you use?"},options:{vi:["Phiên bản mới theo ECN","Phiên bản cũ đang mở","Phiên bản có chi phí thấp nhất","Tùy sản xuất chọn"],en:["The new revision per the ECN","The old open revision","The cheapest revision","Whatever production prefers"]},answer:0,explain:{vi:"Tuần cần vật tư nằm sau ngày hiệu lực nên phải áp phiên bản BOM mới.",en:"The need week is after the effectivity date, so the new BOM revision applies."}},{q:{vi:"Nhu cầu ròng 1030 cái, bội số đóng gói 250. Lượng đặt hàng là bao nhiêu?",en:"Net need is 1030 pcs and the pack multiple is 250. What is the order quantity?"},options:{vi:["1000","1030","1500","1250"],en:["1000","1030","1500","1250"]},answer:3,explain:{vi:"Làm tròn lên bội số 250 gần nhất không nhỏ hơn 1030 là 1250.",en:"Rounding up to the nearest 250 multiple not below 1030 gives 1250."}},{q:{vi:"Nhà cung cấp hứa hoa hồng riêng nếu bạn đặt nhiều hơn số MRP. Bạn làm gì?",en:"A supplier promises a private commission if you order more than MRP says. What do you do?"},options:{vi:["Nhận vì công ty vẫn có hàng","Từ chối, đặt theo MRP và báo cáo bộ phận tuân thủ","Đặt thêm một nửa cho cân bằng","Im lặng và để mua hàng quyết định"],en:["Accept since the company still gets stock","Refuse, order per MRP and report to compliance","Order half the extra as a compromise","Stay silent and let purchasing decide"]},answer:1,explain:{vi:"Nhận lợi ích cá nhân là xung đột lợi ích, gây tồn kho thừa và vi phạm quy tắc ứng xử.",en:"A personal benefit is a conflict of interest, causes excess stock and breaches the code of conduct."}}],tools_en:["ERP MRP module","Inventory analysis spreadsheet","BI reporting tool","Warehouse management system (WMS)","Supplier collaboration portal"]}}})})(window.KKR);
